application.css:
* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #172033; background: #eef2f7; }
body { margin: 0; min-width: .it; }
.page-shell { width: min(100% - 2rem, 920px); margin: 0 auto; padding: 2.5rem 0; }
.page-header { margin-bottom: 1.5rem; }
.eyebrow { margin: 0 0 .35rem; color: #2457a6; font-size: .8rem; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0; font-size: clamp(1.8rem, 5vw, 2.6rem); }
h2 { margin: 0 0 1.25rem; font-size: 1.3rem; }
.page-header p:last-child { margin: .65rem 0 0; color: #4b5870; }
.panel { margin-top: 1.25rem; padding: clamp(1.1rem, 3vw, 1.75rem); border: 1px solid #d6deea; border-radius: .75rem; background: #fff; box-shadow: 0 4px 16px rgba(23,32,51,.06); }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.field { display: flex; flex-direction: column; gap: .4rem; }
.field-wide { grid-column: 1 / -1; }
label { font-weight: 650; font-size: .94rem; }
input, select { width: 100%; min-height: 2.7rem; padding: .55rem .7rem; border: 1px solid #9aa8bd; border-radius: .4rem; background: #fff; color: #172033; font: inherit; }
input:focus, select:focus, button:focus { outline: 3px solid #8bb8ff; outline-offset: 2px; }
button { margin-top: 1.25rem; min-height: 2.75rem; padding: .6rem 1rem; border: 0; border-radius: .4rem; background: #1859a8; color: #fff; font: inherit; font-weight: 700; cursor: pointer; }
button:hover { background: #124682; }
.message { margin: 1rem 0 0; padding: .75rem 1rem; border-radius: .4rem; }
.error { color: #8b1e27; background: #fdebed; border: 1px solid #e8aab0; }
.success { color: #145c38; background: #e8f6ee; border: 1px solid #9bd2b3; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.count { display: inline-grid; place-items: center; min-width: 1.8rem; min-height: 1.8rem; border-radius: 50%; background: #e5edf9; color: #174e91; font-weight: 750; }
.booking-list { display: grid; gap: .85rem; }
.booking { padding: 1rem; border: 1px solid #cbd5e3; border-radius: .5rem; background: #f9fbfe; }
.booking.cancelled { opacity: .7; background: #f1f3f6; }
.booking-top { display: flex; justify-content: space-between; gap: 1rem; align-items: start; }
.booking h3 { margin: 0; font-size: 1.05rem; }
.booking p { margin: .35rem 0; color: #46546b; }
.booking button { margin-top: .5rem; background: #9b2730; }
.booking button:hover { background: #761d24; }
.empty-state { margin: 0; color: #59677d; }
[hidden] { display: none !important; }
@media (max-width: 600px) { .page-shell { width: min(100% - 1rem, 920px); padding: 1.25rem 0; } .form-grid { grid-template-columns: 1fr; } .field-wide { grid-column: auto; } .booking-top { flex-direction: column; } }

application.javascript:
const form = document.querySelector('#booking-form');
const nameInput = document.querySelector('#booking-name');
const emailInput = document.querySelector('#booking-email');
const dateInput = document.querySelector('#booking-date');
const timeInput = document.querySelector('#booking-time');
const typeInput = document.querySelector('#booking-type');
const formError = document.querySelector('#form-error');
const confirmation = document.querySelector('#confirmation');
const bookingList = document.querySelector('#booking-list');
const emptyState = document.querySelector('#empty-state');
const bookingCount = document.querySelector('#booking-count');
let bookings = [];

function getToday() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

function showError(message) {
  formError.textContent = message;
  formError.hidden = false;
  confirmation.hidden = true;
}

function clearMessages() {
  formError.textContent = '';
  formError.hidden = true;
  confirmation.textContent = '';
  confirmation.hidden = true;
}

function formatBooking(booking) {
  const date = new Date(`${booking.date}T00:00:00`);
  return `${date.toLocaleDateString(undefined, { dateStyle: 'long' })} at ${booking.time}`;
}

function renderBookings() {
  bookingList.replaceChildren();
  const activeBookings = bookings.filter((booking) => booking.status === 'active');
  bookingCount.textContent = String(activeBookings.length);
  emptyState.hidden = bookings.length > 0;
  if (bookings.length === 0) {
    bookingList.append(emptyState);
    return;
  }
  bookings.forEach((booking) => {
    const article = document.createElement('article');
    article.className = `booking${booking.status === 'cancelled' ? ' cancelled' : ''}`;
    article.dataset.testid = 'booking';
    article.dataset.status = booking.status;
    const top = document.createElement('div');
    top.className = 'booking-top';
    const heading = document.createElement('h3');
    heading.dataset.testid = 'booking-name-display';
    heading.textContent = booking.name;
    top.append(heading);
    article.append(top);
    const details = document.createElement('p');
    details.textContent = `${booking.type} · ${formatBooking(booking)}`;
    article.append(details);
    const email = document.createElement('p');
    email.textContent = booking.email;
    article.append(email);
    if (booking.status === 'active') {
      const cancel = document.createElement('button');
      cancel.type = 'button';
      cancel.dataset.testid = 'booking-cancel';
      cancel.dataset.id = booking.id;
      cancel.textContent = 'Cancel booking';
      cancel.setAttribute('aria-label', `Cancel booking for ${booking.name}`);
      article.append(cancel);
    } else {
      const status = document.createElement('p');
      status.textContent = 'Cancelled';
      status.className = 'cancelled-label';
      article.append(status);
    }
    bookingList.append(article);
  });
}

function handleSubmit(event) {
  event.preventDefault();
  clearMessages();
  if (!form.checkValidity()) {
    showError('Please complete all fields with valid information.');
    form.reportValidity();
    return;
  }
  if (dateInput.value < getToday()) {
    showError('Please choose today or a future date.');
    dateInput.focus();
    return;
  }
  const booking = { id: `${Date.now()}-${Math.random()}`, name: nameInput.value.trim(), email: emailInput.value.trim(), date: dateInput.value, time: timeInput.value, type: typeInput.value, status: 'active' };
  if (!booking.name) {
    showError('Customer name cannot be empty.');
    nameInput.focus();
    return;
  }
  bookings.push(booking);
  renderBookings();
  confirmation.textContent = `Booking confirmed for ${booking.name}.`;
  confirmation.hidden = false;
  form.reset();
  dateInput.min = getToday();
}

function handleBookingAction(event) {
  const button = event.target.closest('[data-testid="booking-cancel"]');
  if (!button) return;
  const booking = bookings.find((item) => item.id === button.dataset.id);
  if (!booking) return;
  booking.status = 'cancelled';
  renderBookings();
}

dateInput.min = getToday();
form.addEventListener('submit', handleSubmit);
bookingList.addEventListener('click', handleBookingAction);
renderBookings();
